    return (z / SQ2).erf() / 2 + arb(1) / 2

def phi_acb(z):
    return (-(z * z) / 2).exp() / (2 * arb.pi()).sqrt()

def s_density_acb(nu, s):
    nu = arb(nu)
    return nu ** (nu / 2) * s ** (nu - 1) * (-nu * s * s / 2).exp() / (arb(2) ** (nu / 2 - 1) * (nu / 2).gamma())

