    def f(y, analytic):
        prod = arb(1)
        for l, c in zip(lams_a, cs_a):
            up = Phi_acb((d * s - l * y) / c)
            if two_sided:
                up -= Phi_acb((-d * s - l * y) / c)
            prod *= up
        return phi_acb(y) * prod
    core = acb.integral(f, -Y, Y, rel_tol=tol, abs_tol=tol).real
    tail = (Y / SQ2).erfc()
    return core + arb(tail / 2, tail / 2)

